import { useState, useEffect } from "react";
import EntityCard from "./components/EntityCard";

function App() {
  const [entities, setEntities] = useState([]);
  const [input, setInput] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editInput, setEditInput] = useState("");

  useEffect(() => {
    fetch("/api/entities")
      .then(res => res.json())
      .then(data => setEntities(data));
  }, []);

  const handleAdd = () => {
    if (!input.trim()) return;
    fetch("/api/entities", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: input, body: "" })
    })
      .then(res => res.json())
      .then(newEntity => {
        setEntities(prev => [...prev, newEntity]);
        setInput("");
      });
  };

  const handleDelete = (id) => {
    fetch(`/api/entities/${id}`, { method: "DELETE" })
      .then(() => {
        setEntities(prev => prev.filter(e => e.id !== id));
      });
  };

  const handleEdit = (entity) => {
    setEditingId(entity.id);
    setEditInput(entity.title);
  };

  const handleSave = (id) => {
    fetch(`/api/entities/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: editInput, body: "" })
    })
      .then(res => res.json())
      .then(updated => {
        setEntities(prev => prev.map(e => e.id === id ? updated : e));
        setEditingId(null);
        setEditInput("");
      });
  };

  return (
    <div className="container mt-4">
      <h1 className="mb-4">Entities</h1>

      {/* Add */}
      <div className="input-group mb-4">
        <input
          className="form-control"
          value={input}
          onChange={e => setInput(e.target.value)}
          placeholder="Enter title"
        />
        <button className="btn btn-primary" onClick={handleAdd}>Add</button>
      </div>

      {/* Edit form */}
      {editingId && (
        <div className="input-group mb-4">
          <input
            className="form-control"
            value={editInput}
            onChange={e => setEditInput(e.target.value)}
          />
          <button className="btn btn-success" onClick={() => handleSave(editingId)}>Save</button>
          <button className="btn btn-secondary" onClick={() => setEditingId(null)}>Cancel</button>
        </div>
      )}

      {/* Cards */}
      <div className="row">
        {entities.map(entity => (
          <div className="col-md-4" key={entity.id}>
            <EntityCard
              entity={entity}
              onEdit={handleEdit}
              onDelete={handleDelete}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
